panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:54px 60px 0;background:radial-gradient(circle at 12% 30%,rgba(255,153,0,.13),transparent 45%),radial-gradient(circle at 90% 70%,rgba(191,0,0,.11),transparent 48%),var(--cream)}
.k{font-size:28px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:56px;font-weight:900;line-height:1.25;text-align:center;margin-top:6px}
.t em{font-style:normal;color:#BF0000}
.t b{color:#E47911}
.sub{text-align:center;font-size:23px;color:var(--ink-2);font-weight:700;margin-top:10px}
.amzc{color:#E47911}.rk{color:#BF0000;font-weight:900}
.note{position:absolute;left:60px;right:60px;bottom:44px;font-size:24px}

.board{margin-top:34px;background:#fff;border-radius:30px;box-shadow:0 26px 50px -26px rgba(30,18,25,.45);overflow:hidden}
.board .hd,.board .row{display:grid;grid-template-columns:1.25fr 1fr 1fr;align-items:center}
.board .hd span{height:96px;display:flex;align-items:center;justify-content:center;font-size:34px;font-weight:900}
.board .hd .ha{background:#232F3E;border-bottom:8px solid #FF9900}
.board .hd .ha img{height:62px;background:#fff;border-radius:14px;padding:6px 18px}
.board .hd .hr{background:#BF0000;color:#fff;border-bottom:8px solid #8E0000}
.board .row{border-top:2px solid var(--line);min-height:168px}
.nm{padding:0 26px;font-size:32px;font-weight:900;line-height:1.3}
.nm small{display:block;font-size:19px;font-weight:700;color:var(--ink-2)}
.v{text-align:center;font-size:40px;font-weight:900;color:var(--ink-2);height:100%;display:flex;align-items:center;justify-content:center;position:relative}
.v.win{color:#fff}
.v.win.a{background:#232F3E}.v.win.r{background:#BF0000}
.v.win::after{content:"安い";position:absolute;top:14px;right:14px;font-size:20px;background:#F5C518;color:#1E1219;padding:3px 10px;border-radius:999px}

