.duo{display:grid;grid-template-columns:1fr 1fr;gap:26px;margin-top:30px}
.c{border-radius:30px;padding:26px 28px;background:#fff;border:3px solid var(--line);box-shadow:0 20px 40px -26px rgba(30,18,25,.4)}
.c.a.win{border:6px solid #FF9900}.c.r.win{border:6px solid #BF0000}
.lg{height:72px;display:flex;align-items:center;justify-content:center;border-radius:16px}
.c.a .lg{background:#232F3E}.c.a .lg img{height:56px;background:#fff;border-radius:12px;padding:4px 16px}
.rkl{background:#BF0000;color:#fff;font-size:34px;font-weight:900}
.shop{text-align:center;font-size:20px;font-weight:700;color:var(--ink-2);margin:10px 0 6px;min-height:28px}
.ln,.net{display:flex;justify-content:space-between;align-items:baseline;padding:18px 2px;border-top:2px solid var(--line)}
.ln span,.net span{font-size:22px;font-weight:700;color:var(--ink-2)}
.ln b{font-size:40px;font-weight:900}
.net b{font-size:54px;font-weight:900}
.c.a.win .net b{color:#E47911}.c.r.win .net b{color:#BF0000}
.diff{margin-top:40px;text-align:center;font-size:40px;font-weight:900}
.diff em{font-style:normal;background:#F5C518;padding:2px 14px;border-radius:12px}

